function search(nums, target) {
  let low = 0, high = nums.length - 1;
  while (low < high) {                          // find the minimum: the start of the second run
    const mid = low + Math.floor((high - low) / 2);
    if (nums[mid] > nums[high]) low = mid + 1;
    else high = mid;
  }
  const seam = low;
  const last = nums.length - 1;
  [low, high] = target >= nums[seam] && target <= nums[last] ? [seam, last] : [0, seam - 1];   // which run?
  while (low <= high) {                         // plain binary search in that run
    const mid = low + Math.floor((high - low) / 2);
    if (nums[mid] === target) return mid;
    if (nums[mid] < target) low = mid + 1;
    else high = mid - 1;
  }
  return -1;
}

